// Modes: handoff | opt_out | wrong_number. Builds the Salesforce update body,
// urgency, Task subject and the single permitted customer message (if any).
const j = $json;
const mode = j.mode || 'handoff';
const map = JSON.parse($env.SF_FIELD_MAP_JSON || '{}');
const m = map.mappings || {};
const templates = JSON.parse($env.FALLBACK_MESSAGES_JSON || '{}').templates || {};
const handoffRules = JSON.parse($env.HANDOFF_RULES_JSON || '{}');
let resolution = {}; try { resolution = JSON.parse(j.resolution || '{}'); } catch {}
const recordRef = resolution.record_ref || (resolution.sanitized && resolution.sanitized.record_ref) || null;
const recordObj = recordRef ? recordRef.split(':')[0] : null;
const recordId = recordRef ? recordRef.split(':')[1] : (resolution.record_id || null);
const fset = (body, logical, value) => { const s = m[logical]; if (s && s.field !== 'UNMAPPED' && (!recordObj || s.object === recordObj)) body[s.field] = value; };
const sfBody = {};
let taskSubject = null, customerMsg = null, templateId = null, urgency = 'normal', slackText = null;
const assistant = $env.ASSISTANT_NAME || 'Emma';
let history = []; try { history = JSON.parse(j.recent_history || '[]'); } catch {}
const historyText = history.slice(-6).map(h => `${h.dir === 'in' ? 'Customer' : assistant}: ${h.content}`).join('\n');
if (mode === 'opt_out') {
  fset(sfBody, 'sms_opt_out', true);
  fset(sfBody, 'consent_timestamp', new Date().toISOString());
  fset(sfBody, 'consent_source', 'customer_opt_out:' + (j.matched_phrase || 'detected'));
  fset(sfBody, 'conversation_stage', 'DO_NOT_CONTACT');
  customerMsg = templates.opt_out_confirmation || null; templateId = 'opt_out_confirmation';
  taskSubject = `[${assistant} AI] Customer opted out of messaging`;
} else if (mode === 'wrong_number') {
  fset(sfBody, 'wrong_number', true);
  fset(sfBody, 'conversation_stage', 'WRONG_NUMBER');
  customerMsg = templates.wrong_number_apology || null; templateId = 'wrong_number_apology';
  taskSubject = `[${assistant} AI] Wrong number reported — verify phone on record`;
} else {
  fset(sfBody, 'human_takeover', true);
  fset(sfBody, 'handoff_reason', (j.handoff_reason || 'unspecified').slice(0, 250));
  fset(sfBody, 'conversation_stage', 'HUMAN_HANDOFF');
  const sendTransfer = (handoffRules.handoff_actions || {}).send_transfer_message !== false;
  customerMsg = sendTransfer ? (templates.handoff_transfer || null) : null; templateId = 'handoff_transfer';
  const kw = (handoffRules.urgency_keywords || {});
  const txt = historyText.toLowerCase();
  if ((kw.high || []).some(k => txt.includes(k)) || ['complaint', 'fraud_or_identity_theft_report'].includes(j.handoff_reason)) urgency = 'high';
  else if ((kw.medium || []).some(k => txt.includes(k))) urgency = 'medium';
  taskSubject = `[${assistant} AI] Handoff: ${(j.handoff_reason || 'customer needs a human').slice(0, 120)}`;
}
const sfLink = recordId ? `${$env.SF_INSTANCE_URL}/lightning/r/${recordObj}/${recordId}/view` : '(no Salesforce record matched)';
slackText = [`:rotating_light: *${assistant} ${mode === 'handoff' ? 'handoff' : mode.replace('_', ' ')}* (urgency: ${urgency})`,
  `*Reason:* ${j.handoff_reason || j.matched_phrase || mode}`,
  `*Record:* ${sfLink}`,
  `*Correlation:* ${j.correlation_id}`,
  historyText ? `*Recent conversation:*\n${historyText.slice(0, 1500)}` : null].filter(Boolean).join('\n');
console.log(JSON.stringify({ level: 'info', workflow: 'SB-09', workflow_version: '1.0.0', correlation_id: j.correlation_id, action: 'handoff_' + mode, record_ref: recordRef, urgency, ts: new Date().toISOString() }));
return [{ json: { ...j, mode, sfBody, recordObj, recordId, recordRef, taskSubject, customerMsg, template_id: templateId, urgency, slackText, priority: urgency === 'high' ? 'High' : 'Normal' } }];

// Resume requires the shared RESUME_AUTH_TOKEN and an operator identity.
// Rechecks (opt-out, consent, wrong number, global kill switch) run against
// Salesforce in the next node; this node validates the request itself.
const body = $json.body || {};
const headers = $json.headers || {};
const token = headers['x-resume-token'] || body.token || '';
const expected = $env.RESUME_AUTH_TOKEN || '';
let ok = expected.length > 0 && token.length === expected.length;
if (ok) { let d = 0; for (let i = 0; i < expected.length; i++) d |= expected.charCodeAt(i) ^ token.charCodeAt(i); ok = d === 0; }
if (!ok) return [{ json: { authorized: false } }];
if (!body.record_ref || !body.resumed_by) return [{ json: { authorized: false, reason: 'record_ref and resumed_by are required' } }];
return [{ json: { authorized: true, record_ref: body.record_ref, recordObj: body.record_ref.split(':')[0], recordId: body.record_ref.split(':')[1], resumed_by: String(body.resumed_by).slice(0, 80), correlation_id: 'resume_' + Date.now().toString(36) } }];

// Refuses resume when opt-out / wrong-number / missing-consent persists.
const auth = $('Authorize + Recheck').first().json;
const m = (JSON.parse($env.SF_FIELD_MAP_JSON || '{}').mappings || {});
const fname = (k) => { const s = m[k]; return s && s.field !== 'UNMAPPED' && s.object === auth.recordObj ? s.field : null; };
let rec = null;
try { rec = ($('Salesforce: Recheck Before Resume').first().json.records || [])[0] || null; } catch {}
if (!rec) return [{ json: { resumed: false, reason: 'record_not_found_or_query_failed', http: 409 } }];
const val = (k) => { const fn = fname(k); return fn ? String(rec[fn]) === 'true' : null; };
if (val('sms_opt_out') === true) return [{ json: { resumed: false, reason: 'record is opted out — resume refused', http: 409 } }];
if (val('wrong_number') === true) return [{ json: { resumed: false, reason: 'record marked wrong number — resume refused', http: 409 } }];
if (val('sms_consent') === false) return [{ json: { resumed: false, reason: 'no messaging consent on record — resume refused', http: 409 } }];
const body = {};
const ht = fname('human_takeover'); if (ht) body[ht] = false;
const hr = fname('handoff_reason'); if (hr) body[hr] = `resumed by ${auth.resumed_by} at ${new Date().toISOString()}`;
console.log(JSON.stringify({ level: 'info', workflow: 'SB-09', correlation_id: auth.correlation_id, action: 'resume_authorized', record_ref: auth.record_ref, resumed_by: auth.resumed_by, ts: new Date().toISOString() }));
return [{ json: { resumed: true, sfBody: body, recordObj: auth.recordObj, recordId: auth.recordId, http: 200, resumed_by: auth.resumed_by } }];
